      counterstrike2: 'Counter-Strike 2', csgo: 'CS:GO', counterstrike16: 'Counter-Strike 1.6', css: 'Counter-Strike: Source',
      teamfortress2: 'Team Fortress 2', garrysmod: "Garry's Mod", l4d2: 'Left 4 Dead 2',
