  { id: 'asa', label: 'ARK: Survival Ascended', port: 7777, abbr: 'AS', color: '#2f9ea8' },
  { id: 'conanexiles', label: 'Conan Exiles', port: 7777, abbr: 'CE', color: '#a8743a' },
